instead_version '2.3.0'

--package.cpath = './?.so'
require 'luapassing'

require 'prefs'
require 'xact'
require 'nouse'
require 'hideinv'
--require 'para'
require 'dash'
require 'snapshots'
require 'theme'
require 'timer'
require 'modules/nlb'
require 'modules/fonts'
require 'modules/paginator'
require 'modules/vn'
require 'modules/gobj'
game.codepage='UTF-8';
stead.scene_delim = '^';

game.act = function() nlb:curloc().lasttext = 'Nothing happens.'; p(nlb:curloc().lasttext); nlb:curloc().wastext = true; end;
game.inv = function() nlb:curloc().lasttext = 'Hm... This is strange thing...'; p(nlb:curloc().lasttext); nlb:curloc().wastext = true; end;
game.nouse = function() nlb:curloc().lasttext = 'Does not work...'; p(nlb:curloc().lasttext); nlb:curloc().wastext = true; end;
game.forcedsc = false;
paginator.delim = '\n[ \t]*\n'
function exec(s)
    p('$'..s:gsub('\n', '^')..'$^^')
end
function init()
    statsAPI.init();
    if dice then
        paginator:set_onproceed(function()
            dice:hide(true);
            -- Use code below if you want smooth rollout animation and text change on next step
            --if dice:hide() then
            --    return
            --end
        end);
    end
    vn:scene(nil);
    nlbticks = stead.ticks();
    _export_lang = 'en';
    _syscall_showmenubtn:act();
    format.quotes = false;
    if not prefs.achievements_max then
        prefs.achievements_max = {};
    end
    if not prefs.achievements_ids then
        prefs.achievements_ids = {};
    end
    if not prefs.achievements_ids['COMPLETE_MANUAL'] then prefs.achievements_ids['COMPLETE_MANUAL'] = {}; end;
    if not prefs.achievements_ids['DARK_WOLF'] then prefs.achievements_ids['DARK_WOLF'] = {}; end;
    if not prefs.achievements_ids['EVERLASTING_WINTER'] then prefs.achievements_ids['EVERLASTING_WINTER'] = {}; end;
    if not prefs.achievements_ids['EXCESSIVE_VIGILANCE'] then prefs.achievements_ids['EXCESSIVE_VIGILANCE'] = {}; end;
    if not prefs.achievements_ids['FOR_BRAVERY'] then prefs.achievements_ids['FOR_BRAVERY'] = {}; end;
    if not prefs.achievements_ids['FROZEN_PASTRIES'] then prefs.achievements_ids['FROZEN_PASTRIES'] = {}; end;
    if not prefs.achievements_ids['HAG_ALWAYS_ALERT'] then prefs.achievements_ids['HAG_ALWAYS_ALERT'] = {}; end;
    if not prefs.achievements_ids['HAG_ALWAYS_ALERT_2'] then prefs.achievements_ids['HAG_ALWAYS_ALERT_2'] = {}; end;
    if not prefs.achievements_ids['HAG_PAYS_A_VISIT'] then prefs.achievements_ids['HAG_PAYS_A_VISIT'] = {}; end;
    if not prefs.achievements_ids['HAG_PAYS_A_VISIT_2'] then prefs.achievements_ids['HAG_PAYS_A_VISIT_2'] = {}; end;
    if not prefs.achievements_ids['NO_GRANNYS_FOREST'] then prefs.achievements_ids['NO_GRANNYS_FOREST'] = {}; end;
    if not prefs.achievements_ids['PASTRIES_UTILIZER'] then prefs.achievements_ids['PASTRIES_UTILIZER'] = {}; end;
    if not prefs.achievements_ids['POOR_COOK'] then prefs.achievements_ids['POOR_COOK'] = {}; end;
    if not prefs.achievements_ids['ROMANTIC_MEETING'] then prefs.achievements_ids['ROMANTIC_MEETING'] = {}; end;
    if not prefs.achievements_ids['SNOWMAN'] then prefs.achievements_ids['SNOWMAN'] = {}; end;
