        if w.nlbid == v_612d73db_7e86_4ba4_86b3_f88d7ba56a9e.nlbid then
            if ( not _vaseWithWater) then
            
_lookedAtVase = true;

            end;
        end;
        if 
w.nlbid == v_8dafc520_f04e_40d3_a151_c3fea533dc01.nlbid then
                        if have(stead.deref(_tutVaseObj)) then remove(stead.deref(_tutVaseObj), inv()); end;
                nlb:addf(v_8dafc520_f04e_40d3_a151_c3fea533dc01, v_612d73db_7e86_4ba4_86b3_f88d7ba56a9e, false);
    _hasVase =  false ;

