        if w.nlbid == v_612d73db_7e86_4ba4_86b3_f88d7ba56a9e.nlbid then
            if ( not _vaseWithWater) then
local t = "A medium size vase with a large neck. "; nlb:curloc().lasttext = nlb:lasttext()..t; p(t); nlb:curloc().wastext = true; wasnouses = false;
            else
local t = "A vase with water. "; nlb:curloc().lasttext = nlb:lasttext()..t; p(t); nlb:curloc().wastext = true; wasnouses = false;
            end;
        end;
        if 
w.nlbid == v_8dafc520_f04e_40d3_a151_c3fea533dc01.nlbid then
local t = "Red Riding Hood put the vase on the table. "; nlb:curloc().lasttext = nlb:lasttext()..t; p(t); nlb:curloc().wastext = true; wasnouses = false;
        if wasnouses then nlb:curloc().lasttext = prevt; end;
        end;
        return not wasnouses;
    end,
};

